#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long m;
    cin >> n >> m;
    vector<long long> value(n);
    for (int i = 0; i < n; i++) cin >> value[i];
    vector<vector<long long>> edges(m, vector<long long>(2));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> edges[i][j];
        }
    }

    vector<vector<int>> adj(n + 1);
    for (const vector<long long>& e : edges) adj[e[0]].push_back((int)e[1]);
    const int NN = (int)(n);
    vector<vector<int>> radj(NN + 1);
    for (int u = 1; u <= NN; u++) {
        for (int v : adj[u]) radj[v].push_back(u);
    }
    vector<int> order, pos(NN + 1, 0);
    vector<char> seen(NN + 1, 0);
    for (int s = 1; s <= NN; s++) {
        if (seen[s]) continue;
        seen[s] = 1;
        vector<int> stack = {s};
        while (!stack.empty()) {
            int v = stack.back();
            if (pos[v] < (int)adj[v].size()) {
                int w = adj[v][pos[v]++];
                if (!seen[w]) {
                    seen[w] = 1;
                    stack.push_back(w);
                }
            } else {
                order.push_back(v);
                stack.pop_back();
            }
        }
    }
    vector<int> comp(NN + 1, -1);
    int compCount = 0;
    for (size_t i = order.size(); i-- > 0;) {
        int s = order[i];
        if (comp[s] != -1) continue;
        comp[s] = compCount;
        vector<int> stack = {s};
        while (!stack.empty()) {
            int v = stack.back();
            stack.pop_back();
            for (int w : radj[v]) {
                if (comp[w] == -1) {
                    comp[w] = compCount;
                    stack.push_back(w);
                }
            }
        }
        compCount++;
    }
    vector<long long> total(compCount, 0);
    vector<vector<int>> members(compCount);
    for (int v = 1; v <= NN; v++) {
        total[comp[v]] += value[v - 1];
        members[comp[v]].push_back(v);
    }
    vector<long long> best = total;
    for (int c = 0; c < compCount; c++) {
        for (int v : members[c]) {
            for (int w : adj[v]) {
                int d = comp[w];
                if (d != c && best[c] + total[d] > best[d]) best[d] = best[c] + total[d];
            }
        }
    }
    cout << *max_element(best.begin(), best.end()) << "\n";

    return 0;
}

