import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long m = Long.parseLong(next());
        long[] value = new long[(int) n];
        for (int i = 0; i < value.length; i++) value[i] = Long.parseLong(next());
        long[][] edges = new long[(int) m][2];
        for (int i = 0; i < edges.length; i++) {
            for (int j = 0; j < edges[i].length; j++) {
                edges[i][j] = Long.parseLong(next());
            }
        }

        int nodes = (int) n;
        int[] eu = new int[edges.length];
        int[] ev = new int[edges.length];
        for (int i = 0; i < edges.length; i++) {
            eu[i] = (int) edges[i][0];
            ev[i] = (int) edges[i][1];
        }
        final int NN = (int) (nodes);
        int[] fHead = new int[NN + 2];
        int[] rHead = new int[NN + 2];
        for (int i = 0; i < eu.length; i++) {
            fHead[eu[i] + 1]++;
            rHead[ev[i] + 1]++;
        }
        for (int v = 1; v <= NN; v++) {
            fHead[v + 1] += fHead[v];
            rHead[v + 1] += rHead[v];
        }
        int[] fTo = new int[eu.length];
        int[] rTo = new int[eu.length];
        int[] fFill = new int[NN + 2];
        int[] rFill = new int[NN + 2];
        for (int i = 0; i < eu.length; i++) {
            int a = eu[i], b = ev[i];
            fTo[fHead[a] + fFill[a]] = b;
            fFill[a]++;
            rTo[rHead[b] + rFill[b]] = a;
            rFill[b]++;
        }
        int[] order = new int[NN];
        int orderSize = 0;
        int[] pos = new int[NN + 2];
        boolean[] seen = new boolean[NN + 2];
        int[] stack = new int[NN + 2];
        for (int s = 1; s <= NN; s++) {
            if (seen[s]) continue;
            seen[s] = true;
            int top = 0;
            stack[top++] = s;
            while (top > 0) {
                int v = stack[top - 1];
                if (fHead[v] + pos[v] < fHead[v + 1]) {
                    int w = fTo[fHead[v] + pos[v]];
                    pos[v]++;
                    if (!seen[w]) {
                        seen[w] = true;
                        stack[top++] = w;
                    }
                } else {
                    order[orderSize++] = v;
                    top--;
                }
            }
        }
        int[] comp = new int[NN + 2];
        Arrays.fill(comp, -1);
        int compCount = 0;
        for (int i = orderSize - 1; i >= 0; i--) {
            int s = order[i];
            if (comp[s] != -1) continue;
            comp[s] = compCount;
            int top = 0;
            stack[top++] = s;
            while (top > 0) {
                int v = stack[--top];
                for (int k = rHead[v]; k < rHead[v + 1]; k++) {
                    int w = rTo[k];
                    if (comp[w] == -1) {
                        comp[w] = compCount;
                        stack[top++] = w;
                    }
                }
            }
            compCount++;
        }
        long[] total = new long[compCount];
        int[] start = new int[compCount + 1];
        for (int v = 1; v <= NN; v++) {
            total[comp[v]] += value[v - 1];
            start[comp[v] + 1]++;
        }
        for (int c = 0; c < compCount; c++) start[c + 1] += start[c];
        int[] members = new int[NN];
        int[] filled = new int[compCount];
        for (int v = 1; v <= NN; v++) {
            members[start[comp[v]] + filled[comp[v]]] = v;
            filled[comp[v]]++;
        }
        long[] best = total.clone();
        for (int c = 0; c < compCount; c++) {
            for (int i = start[c]; i < start[c + 1]; i++) {
                int v = members[i];
                for (int k = fHead[v]; k < fHead[v + 1]; k++) {
                    int d = comp[fTo[k]];
                    if (d != c && best[c] + total[d] > best[d]) best[d] = best[c] + total[d];
                }
            }
        }
        long answer = 0;
        for (long x : best) answer = Math.max(answer, x);
        System.out.println(answer);
    }
}
